version: "2"
sql:
  - engine: "sqlite"
    schema: "schema.sql"
    queries: "queries"
    gen:
      go:
        package: "gen"
        out: "gen"
        emit_json_tags: true
        emit_pointers_for_null_types: true
---QUERIES---
-- name: ListActivitiesByResource :many
SELECT * FROM activity WHERE resource_type = ? AND resource_id = ? ORDER BY created_at DESC;

-- name: CreateActivity :one
INSERT INTO activity (id, resource_type, resource_id, action, data, created_at)
VALUES (?, ?, ?, ?, ?, ?)
RETURNING *;
-- name: ListColumnsByProject :many
SELECT * FROM column WHERE project_id = ? ORDER BY position, created_at;

-- name: CountColumnsByProject :one
SELECT COUNT(*) FROM column WHERE project_id = ?;

-- name: GetColumn :one
SELECT * FROM column WHERE id = ?;

-- name: CreateColumn :one
INSERT INTO column (id, project_id, name, position, created_at)
VALUES (?, ?, ?, ?, ?)
RETURNING *;

-- name: UpdateColumnName :one
UPDATE column SET name = ? WHERE id = ? RETURNING *;

-- name: SetColumnPosition :exec
UPDATE column SET position = ? WHERE id = ?;

-- name: DeleteColumn :execrows
DELETE FROM column WHERE id = ?;
-- name: ListCommentsByTask :many
SELECT * FROM comment WHERE task_id = ? ORDER BY created_at;

-- name: GetComment :one
SELECT * FROM comment WHERE id = ?;

-- name: CreateComment :one
INSERT INTO comment (id, task_id, content, created_at)
VALUES (?, ?, ?, ?)
RETURNING *;

-- name: DeleteComment :execrows
DELETE FROM comment WHERE id = ?;
-- name: ListLabelsByWorkspace :many
SELECT * FROM label WHERE workspace_id = ? ORDER BY created_at;

-- name: GetLabel :one
SELECT * FROM label WHERE id = ?;

-- name: CreateLabel :one
INSERT INTO label (id, workspace_id, name, color, created_at)
VALUES (?, ?, ?, ?, ?)
RETURNING *;

-- name: UpdateLabel :one
UPDATE label SET name = ?, color = ? WHERE id = ? RETURNING *;

-- name: DeleteLabel :execrows
DELETE FROM label WHERE id = ?;

-- name: ListTaskLabelsByProject :many
SELECT tl.task_id, l.* FROM task_label tl
JOIN label l ON l.id = tl.label_id
WHERE tl.task_id IN (SELECT id FROM task WHERE project_id = ?);

-- name: ListTaskLabelsByTask :many
SELECT l.* FROM task_label tl JOIN label l ON l.id = tl.label_id WHERE tl.task_id = ? ORDER BY l.created_at;
-- name: AttachLabel :exec
INSERT OR IGNORE INTO task_label (task_id, label_id) VALUES (?, ?);

-- name: DetachLabel :exec
DELETE FROM task_label WHERE task_id = ? AND label_id = ?;
-- name: ListProjectsByWorkspace :many
SELECT * FROM project WHERE workspace_id = ? ORDER BY position, created_at;

-- name: GetProject :one
SELECT * FROM project WHERE id = ?;

-- name: CountProjectsByWorkspace :one
SELECT COUNT(*) FROM project WHERE workspace_id = ?;

-- name: CreateProject :one
INSERT INTO project (id, workspace_id, name, position, created_at)
VALUES (?, ?, ?, ?, ?)
RETURNING *;

-- name: UpdateProjectName :one
UPDATE project SET name = ? WHERE id = ? RETURNING *;

-- name: DeleteProject :execrows
DELETE FROM project WHERE id = ?;
-- name: ListTasksByProject :many
SELECT * FROM task WHERE project_id = ? ORDER BY position, created_at;

-- name: ListTasksByColumn :many
SELECT * FROM task WHERE column_id = ? ORDER BY position, created_at;

-- name: GetTask :one
SELECT * FROM task WHERE id = ?;

-- name: MaxTaskPositionByColumn :one
SELECT COALESCE(MAX(position), -1) + 1 FROM task WHERE column_id = ?;

-- name: CreateTask :one
INSERT INTO task (id, project_id, column_id, title, description, position, created_at, updated_at)
VALUES (?, ?, ?, ?, ?, ?, ?, ?)
RETURNING *;

-- name: UpdateTask :one
UPDATE task SET title = ?, description = ?, updated_at = ? WHERE id = ? RETURNING *;

-- name: SetTaskPosition :exec
UPDATE task SET column_id = ?, position = ?, updated_at = ? WHERE id = ?;

-- name: DeleteTask :execrows
DELETE FROM task WHERE id = ?;
-- name: CountWorkspaces :one
SELECT COUNT(*) FROM workspace;

-- name: ListWorkspaces :many
SELECT * FROM workspace ORDER BY created_at;

-- name: GetWorkspace :one
SELECT * FROM workspace WHERE id = ?;

-- name: CreateWorkspace :one
INSERT INTO workspace (id, name, created_at)
VALUES (?, ?, ?)
RETURNING id, name, created_at;

-- name: UpdateWorkspaceName :one
UPDATE workspace SET name = ? WHERE id = ? RETURNING id, name, created_at;

-- name: DeleteWorkspace :execrows
DELETE FROM workspace WHERE id = ?;
---MODELS HEAD---
